sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float across;
uniform float down;
uniform float rowOffset;
uniform float mortar;
layout(color) uniform half4 mortarColor;
uniform float mode;
uniform float variation;
uniform float bevel;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 n = float2(max(floor(across + 0.5), 1.0), max(floor(down + 0.5), 1.0));
    float2 uv = coord / size * n;
    uv.x += floor(uv.y) * rowOffset;
    float2 cell = floor(uv);
    float2 f = fract(uv);
    float2 bs = size / n;
    float2 edgePx = min(f, 1.0 - f) * bs;
    float m = smoothstep(mortar * 0.5, mortar * 0.5 + 1.0, min(edgePx.x, edgePx.y));
    float4 samp = mode < 0.5 ? tex(f * size) : tex((floor(coord / bs) + 0.5) * bs);
    float v = 1.0 + (hash21(cell) - 0.5) * variation;
    float lit = 1.0 + bevel * 0.5 * (f.y < 0.5 ? (1.0 - smoothstep(0.0, 0.15, f.y)) : -(1.0 - smoothstep(0.0, 0.15, 1.0 - f.y)));
    float3 col = mix(float3(mortarColor.rgb), unp(samp) * v * lit, m);
    return fin(c, float4(saturate(col) * samp.a, samp.a), opacity);
}
